def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    total_d = 0
    unprov_total = 0
    punish_total = 0

    for i in range(n):
        o = history[i][1]
        if o == 'D':
            total_d += 1
            if i == 0 or history[i - 1][0] == 'C':
                unprov_total += 1
            if i > 0 and history[i - 1][0] == 'D':
                punish_total += 1

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    opp_c_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            opp_c_streak += 1
        else:
            break

    my_last, opp_last = history[-1]

    if total_d >= 35 and n >= 25:
        return 'D'

    if opp_d_streak >= 6:
        return 'D'
    if n >= 90 and opp_d_streak >= 3:
        return 'D'
    if n >= 70 and opp_d_streak >= 4:
        return 'D'
    if n >= 50 and opp_d_streak >= 5:
        return 'D'

    if unprov_total >= 6 and opp_c_streak <= 3:
        return 'D'

    if opp_last == 'D':
        return 'C'

    if punish_total == 0:
        dc_tail = 0
        for i in range(n - 1, -1, -1):
            if history[i][0] == 'D' and history[i][1] == 'C':
                dc_tail += 1
            else:
                break

        if dc_tail >= 2:
            return 'D'

        if (
            n >= 2
            and history[-2][0] == 'D'
            and history[-2][1] == 'C'
            and history[-1][0] == 'C'
            and history[-1][1] == 'C'
        ):
            return 'D'

        if (
            n >= 3
            and history[-3][0] == 'D'
            and history[-3][1] == 'C'
            and history[-2][0] == 'C'
            and history[-2][1] == 'C'
            and history[-1][0] == 'D'
            and history[-1][1] == 'C'
        ):
            return 'D'

    if my_last == 'D':
        return 'C'

    if (
        opp_c_streak >= 5
        and punish_total == 0
        and unprov_total <= 5
        and total_d <= 5
    ):
        if n >= 95:
            if rng.random() < 0.20:
                return 'D'
        elif n >= 85:
            if rng.random() < 0.05:
                return 'D'
        elif n < 93:
            if rng.random() < 0.02:
                return 'D'

    return 'C'
